'use strict';

/**
* Compute the arithmetic mean of a single-precision floating-point strided array ignoring `NaN` values and using an improved Kahan-Babuska algorithm.
*
* @module @stdlib/stats/strided/snanmeankbn
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var snanmeankbn = require( '@stdlib/stats/strided/snanmeankbn' );
*
* var x = new Float32Array( [ 1.0, NaN, 2.0, NaN, 3.0 ] );
*
* var v = snanmeankbn( x.length, x, 1 );
* // returns 2.0
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var snanmeankbn = require( '@stdlib/stats/strided/snanmeankbn' );
*
* var x = new Float32Array( [ 1.0, 10.0, NaN, 20.0, 3.0, 30.0 ] );
*
* var v = snanmeankbn.ndarray( 3, x, 2, 1 );
* // returns 20.0
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var snanmeankbn;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	snanmeankbn = main;
} else {
	snanmeankbn = tmp;
}


// EXPORTS //

module.exports = snanmeankbn;

// exports: { "ndarray": "snanmeankbn.ndarray" }
